const lat1 = 37.7749, lon1 = -122.4194; // San Francisco, CA
const lat2 = 42.3388, lon2 = -71.0726;  // Boston, MA 02118

const R = 3958.8; // Earth radius in miles
const dLat = (lat2 - lat1) * Math.PI / 180;
const dLon = (lon2 - lon1) * Math.PI / 180;
const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLon/2)**2;
const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
const miles = R * c;
const km = miles * 1.60934;

console.log('=== Distance Estimate ===');
console.log('From:  San Francisco, CA (37.7749°N, 122.4194°W)');
console.log('To:    4829 Elm Ridge Way, Suite 7, Boston, MA 02118, USA (~42.3388°N, 71.0726°W)');
console.log('');
console.log('Straight-line (great-circle) distance:');
console.log('  ' + miles.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' miles');
console.log('  ' + km.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' km');
"
